"""Conway's Game of Life generated by compiled weights: a glider gun on a torus."""

from firebrand import compile_machine
from firebrand.machines.life import GOSPER_GLIDER_GUN, LifeSpec, place


def main():
    spec = LifeSpec(width=40, height=20, generations=60)
    model = compile_machine(spec.machine())
    grid = place(spec, GOSPER_GLIDER_GUN, x=1, y=1)
    trace = model.generate(spec.encode(grid), spec.max_context - spec.cells, backend="c")
    expected = grid
    for generation, cells in enumerate(spec.grids(trace)):
        assert (cells == expected).all(), f"generation {generation} differs from NumPy Life"
        expected = spec.step(expected)
    print(f"Generation {spec.generations}, from {len(trace) - spec.cells:,} generated tokens:")
    print("\n".join("".join(".#"[c] for c in row) for row in spec.grids(trace)[-1]))
    print(
        f"{spec.generations} generations equal to NumPy Life; "
        f"{model.config['heads']} heads, {model.config['layers']} layers"
    )


if __name__ == "__main__":
    main()
